int maxProduct(int[] nums) {
    int hi = nums[0], lo = nums[0], best = nums[0];   // largest and smallest product ending here
    for (int i = 1; i < nums.length; i++) {
        int x = nums[i];
        if (x < 0) {                             // a negative turns the smallest into the largest
            int t = hi;
            hi = lo;
            lo = t;
        }
        hi = Math.max(x, hi * x);                // start fresh at x, or extend
        lo = Math.min(x, lo * x);
        best = Math.max(best, hi);
    }
    return best;
}

