function maxProduct(nums) {
  const n = nums.length;
  let best = -Infinity, left = 1, right = 1;
  for (let i = 0; i < n; i++) {
    left = (left === 0 ? 1 : left) * nums[i];              // prefix product, restarting after a zero
    right = (right === 0 ? 1 : right) * nums[n - 1 - i];   // suffix product, the same from the right
    best = Math.max(best, left, right);
  }
  return best;
}

int maxProduct(int[] nums) {
    int n = nums.length, best = Integer.MIN_VALUE, left = 1, right = 1;
    for (int i = 0; i < n; i++) {
        left = (left == 0 ? 1 : left) * nums[i];               // prefix product, restarting after a zero
        right = (right == 0 ? 1 : right) * nums[n - 1 - i];    // suffix product, the same from the right
        best = Math.max(best, Math.max(left, right));
    }
    return best;
}

int maxProduct(vector<int>& nums) {
    int n = nums.size(), best = INT_MIN, left = 1, right = 1;
    for (int i = 0; i < n; i++) {
        left = (left == 0 ? 1 : left) * nums[i];               // prefix product, restarting after a zero
        right = (right == 0 ? 1 : right) * nums[n - 1 - i];    // suffix product, the same from the right
        best = max({best, left, right});
    }
    return best;
}
